drop function if exists public.admin_replace_media(p_old uuid, p_new uuid);
drop function if exists public.admin_restore_content_version(p_key text, p_locale text, p_version integer);
drop function if exists public.admin_save_content_draft(p_key text, p_locale text, p_title text, p_body jsonb, p_base timestamp with time zone);
