revoke all on function public._promotion_for(p_code text, p_in date, p_out date, p_types uuid[], p_strict boolean) from public, anon, authenticated, service_role;
grant execute on function public._promotion_for(p_code text, p_in date, p_out date, p_types uuid[], p_strict boolean) to service_role;
revoke all on function public._quote(p_types uuid[], p_plans uuid[], p_in date, p_out date, p_promo text, p_strict boolean) from public, anon, authenticated, service_role;
grant execute on function public._quote(p_types uuid[], p_plans uuid[], p_in date, p_out date, p_promo text, p_strict boolean) to service_role;
revoke all on function public._reserve(p_source text, p_status text, p_check_in date, p_check_out date, p_adults integer, p_children integer, p_types uuid[], p_plans uuid[], p_promo text, p_guest_name text, p_email text, p_phone text, p_country text, p_arrival text, p_requests text, p_notes text, p_pickup boolean, p_payment_option text, p_idempotency_key text, p_exclude_hold uuid) from public, anon, authenticated, service_role;
grant execute on function public._reserve(p_source text, p_status text, p_check_in date, p_check_out date, p_adults integer, p_children integer, p_types uuid[], p_plans uuid[], p_promo text, p_guest_name text, p_email text, p_phone text, p_country text, p_arrival text, p_requests text, p_notes text, p_pickup boolean, p_payment_option text, p_idempotency_key text, p_exclude_hold uuid) to service_role;
revoke all on function public._site_content_stamp() from public, anon, authenticated, service_role;
grant execute on function public._site_content_stamp() to service_role;
revoke all on function public.admin_update_task(p_task uuid, p_status text, p_notes text) from public, anon, authenticated, service_role;
grant execute on function public.admin_update_task(p_task uuid, p_status text, p_notes text) to authenticated, service_role;
revoke all on function public.confirm_hold(p_token text, p_idempotency_key text, p_guest_name text, p_email text, p_phone text, p_country text, p_arrival text, p_requests text, p_airport_pickup boolean, p_payment_option text, p_quoted_total integer) from public, anon, authenticated, service_role;
